1	// sim_control.hpp #include's htif/sys_call.hpp *inside* the SimControl class
2	// body (see that file's own header comment), so sys_call.hpp's own <sys/
3	// stat.h>/<fcntl.h>/<unistd.h> includes land at class scope instead of global
4	// scope unless something already pulled them in at global scope first -- the
5	// production build gets this for free via an earlier transitive include;
6	// a standalone test does not, so pull them in explicitly, first.
7	#include <fcntl.h>
8	#include <sys/stat.h>
9	#include <unistd.h>
10	
11	#include "platform/sim_control.hpp"
12	
13	#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
14	#include <doctest.h>
15	
16	#include <array>
17	#include <cstdint>
18	#include <cstring>
19	
20	namespace {
21	
22	// Mirrors the real ax66_makatau bug: its guest programs place DRAM (stack,
23	// heap, globals -- including the HTIF magicmem struct) at an "alias" base
24	// (RAM_ALIAS_BASE, 0x800000000 in production) instead of the primary base
25	// (0x0) every other engine uses. Small synthetic bases here keep the backing
26	// buffer tiny; the bug reproduces at any base gap, not just the real one.
27	constexpr uint64_t kPrimaryBase = 0x0;
28	constexpr uint64_t kAliasBase = 0x2000;
29	// Must cover both the correct offset and the bug's wrongly-computed offset,
30	// so a still-buggy dispatch()/guest_va_to_host() reads/writes a wrong-but-
31	// in-bounds location instead of corrupting unrelated memory.
32	constexpr uint64_t kBufEnd = 0x2fff;
33	
34	struct Fixture
35	{
