// Execute one staged syscall in place: args[0] holds the syscall number
// on entry and the return value on exit. Shared by every transport that
// stages the eight-slot arg block (RAM magicmem via dispatch()).
void run_syscall(uint64_t (&args)[MAGIC_MEM_SIZE])
{
  spdlog::debug("sim_control: args: {:#x}, {:#x}, {:#x}, "
                "{:#x}, {:#x}, {:#x}, {:#x}",
                args[0], args[1], args[2], args[3], args[4], args[5],
                args[6]);

  const auto syscall_num = args[0];
  if (syscall_num >= SYSCALL_TABLE_SIZE || !sim_syscall_table[syscall_num]) {
    spdlog::critical("sim_control: invalid syscall number {}", syscall_num);
    args[0] = static_cast<uint64_t>(-1);
    return;
  }
  args[0] = (this->*sim_syscall_table[syscall_num])(
    args[1], args[2], args[3], args[4], args[5], args[6], args[7]);
}

void dispatch(command_t cmd)
{
  uint64_t syscall_args[MAGIC_MEM_SIZE];
  auto addr_offset = cmd.payload() - data_region.base_for(cmd.payload());
  auto src = data_region.data.begin() + addr_offset;

  std::copy(src, src + sizeof(syscall_args),
            reinterpret_cast<uint8_t*>(syscall_args));

  run_syscall(syscall_args);

  std::copy(reinterpret_cast<uint8_t*>(syscall_args),
            reinterpret_cast<uint8_t*>(syscall_args) + sizeof(syscall_args),
            src);
}

