  // One MMIO access as the guest's uncached load/store would arrive.
  void mmio(tlm::tlm_command cmd, uint64_t addr, uint8_t* data, unsigned len)
  {
    tlm::tlm_generic_payload gp;
    gp.set_command(cmd);
    gp.set_address(addr);
    gp.set_data_ptr(data);
    gp.set_data_length(len);
    gp.set_response_status(tlm::TLM_INCOMPLETE_RESPONSE);
    sc_core::sc_time delay = sc_core::SC_ZERO_TIME;
    sim_control.b_transport(gp, delay);
  }

  void mmio_write_u64(uint64_t addr, uint64_t value)
  {
    std::array<uint8_t, 8> bytes;
    std::memcpy(bytes.data(), &value, 8);
    mmio(tlm::TLM_WRITE_COMMAND, addr, bytes.data(), 8);
  }

  // Sentinel-primed read: with no read support the sentinel survives, so a
  // missing implementation fails the assertion instead of passing on luck.
  uint64_t mmio_read_u64(uint64_t addr)
  {
    uint64_t value = 0xdeadbeefdeadbeefULL;
    std::array<uint8_t, 8> bytes;
    std::memcpy(bytes.data(), &value, 8);
    mmio(tlm::TLM_READ_COMMAND, addr, bytes.data(), 8);
    std::memcpy(&value, bytes.data(), 8);
    return value;
  }

  // One 64-bit HTIF command write, as the guest's htif_syscall() does: the
  // command's low 48 bits are the guest's pointer to its magicmem struct.
