// region starts at 0x0 (Tier-1, no shared mem), 0x80000000 (Tier-2,
// --shared-mem-base, narrowed RAM), or the guest maps DRAM through an
// alias_region entirely (ax66's DDR3_MEM_BASE 0x800000000). Without this, a
// guest VA outside `region` resolves against the wrong base and can index
// far outside the owned/mmap buffer.
template<typename T = uint8_t>
inline T* guest_va_to_host(uint64_t va)
{
  const uint64_t window_base = region.base_address + SYSCALL_WINDOW_OFFSET;
  if (va >= window_base && va < window_base + SYSCALL_WINDOW_SIZE)
    return reinterpret_cast<T*>(window_.data() + (va - window_base));
  const uint64_t off = va - data_region.base_for(va);
  return reinterpret_cast<T*>(data_region.data.data() + off);
}

